} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;&lt;i&gt;Le personnage lance ses sorts comme s’ils &#233;taient d’un niveau sup&#233;rieur.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Cat&#233;gorie&lt;/b&gt; : &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;m&#233;tamagie&lt;/a&gt;&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Avantage.&lt;/b&gt; Ce don permet d’amplifier l’intensit&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Sort.html&quot; title=&quot;sort&quot;&gt;sort&lt;/a&gt; choisi en augmentant son &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau effectif&lt;/a&gt; (d’un ou plusieurs &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveaux&lt;/a&gt;, sans toutefois d&#233;passer le 9e). Contrairement aux autres &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#METAMAGIE&quot; title=&quot;Les dons&quot;&gt;dons de m&#233;tamagie&lt;/a&gt;, il augmente r&#233;ellement le &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau de sort&lt;/a&gt; modifi&#233;. Toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;propri&#233;t&#233;s du sort&lt;/a&gt; qui d&#233;pendent de son &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau&lt;/a&gt; (comme le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de son &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; et sa capacit&#233; &#224; traverser un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Globe-Dinvuln&#233;rabilit&#233;-Partielle.html&quot; title=&quot;Globe d&amp;#39;invuln&#233;rabilit&#233; partielle&quot;&gt;globe d&#39;invuln&#233;rabilit&#233; partielle&lt;/a&gt;&lt;/i&gt;) sont calcul&#233;es en fonction de son nouveau &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau&lt;/a&gt;, choisi par le personnage. Un &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Sort.html&quot; title=&quot;sort&quot;&gt;sort&lt;/a&gt; &#224; intensit&#233; augment&#233;e n&#233;cessite un &lt;a class=&quot;pagelink&quot; href=&quot;Emplacement-De-Sort.html&quot; title=&quot;emplacement de sort&quot;&gt;emplacement de sort&lt;/a&gt; &#233;gal &#224; son nouveau &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Niveau.html&quot; title=&quot;Niveau de sort&quot;&gt;niveau&lt;/a&gt; effectif.
